head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05923";
// 원본 : /lstproc/ULDSTF05923.gfm (상장원부(ELW))
/*
 * 화면 동작
 *  - [종목 찾기](ULDSTF92017 상장종목찾기)로 ELW 종목을 고르면 상장원부 상세·유동성공급자·기초자산을 조회한다(진입 시 조회 없음).
 *  - 일부 항목(기관 콤보·표준구분·권리형태·외국인투자한도·중도상환여부·권리내용·결제 사항·호가스프레드 등)을 고쳐 [수정] 한다.
 *    수정은 검증(종목 선택) → 확인 → 업무처리번호 채번 → modify 순서이고, 성공하면 다시 조회한다.
 *  - 기관·주간사 콤보의 전체 목록 API 는 명세에 없다 — 조회한 현재 값만 목록에 넣어 보여 준다(결과서 §10 #3).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05923/ULDSTF05923.md (§번호는 이 문서의 절)
 */

// 화면 상태값
scwin.trJob = "";           // 처리구분 U: 수정 (원본 TR_JOB — 이 화면은 수정만 있다)

// 고정값
scwin.BZ_PROCS_NO_LEN = 14;     // 업무처리번호 자릿수 (원본 vBzProcsNo.length != 14 검사)

// 기관·주간사 콤보 ↔ 조회 응답(dma_detail) 코드·명 키 — 목록 API 가 없어 현재 값을 목록에 넣을 때 쓴다(§6.4)
scwin.INST_COMBOS = [
    { comp : "cmb_PAY_BK_INST_CD", list : "dlt_instCd", codeCol : "instCd", nameCol : "instNm", codeKey : "payBkInstCd", nameKey : "payBkInstNm" },
    { comp : "cmb_UDWRT_INST_CD", list : "dlt_instCd", codeCol : "instCd", nameCol : "instNm", codeKey : "udwrtInstCd", nameKey : "udwrtInstNm" },
    { comp : "cmb_BZAGNT_INST_CD", list : "dlt_instCd", codeCol : "instCd", nameCol : "instNm", codeKey : "bzagntInstCd", nameKey : "bzagntInstNm" },
    { comp : "cmb_DEPO_INST_CD", list : "dlt_instCd", codeCol : "instCd", nameCol : "instNm", codeKey : "depoInstCd", nameKey : "depoInstNm" },
    { comp : "cmb_LEADCOM_MBR_NO", list : "dlt_leadCom", codeCol : "leadcomMbrNo", nameCol : "leadcomMbrNm", codeKey : "leadcomMbrNo", nameKey : "leadcomMbrNm" }
];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 공통 코드 콤보 7종 → (기관·주간사 목록: API 없음) → 달력 바인딩. 진입 시 조회는 없다(종목을 골라야 조회). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 공통 코드 콤보 7종 — 원본 fn_searchCode(elw_recv_common.js)의 CD_ID_M 일괄 조회(동기)
    await $c.data.setCommonCode([{
        code : ["TRANSSTK_AGNT_CD", "ELW_OBJ_IDX_TP_CD", "ELW_RGHT_TP_KIND_CD", "AUTO_EXER_TP_CD", "ELW_RGHT_TP_CD", "EXER_TP_CD", "FNC_ULY_TP_CD"],
        compID : ["cmb_TRANSSTK_AGNT_CD", "cmb_ELW_OBJ_IDX_TP_CD", "cmb_ELW_RGHT_TP_KIND_CD", "cmb_AUTO_EXER_TP_CD", "cmb_ELW_RGHT_TP_CD", "cmb_ELW_EXER_TP_CD", "cmb_FNC_ULY_TP_CD"]
    }]);

    // 2) 기관·주간사 콤보 목록 — 원본 fn_SetInstCdComboCode(/CodeAction.do listInstCd·listLeadCom) + CopyDataSet 4회
    // TODO: 신규 API 명세에 기관코드·주간사 목록 API 가 없다. 확정되면 dlt_instCd·dlt_leadCom 을 채운다 (§10 #3)
    dlt_instCd.removeAll();
    dlt_leadCom.removeAll();

    // 3) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_SUBS_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ISU_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_PAY_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_EXP_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ELW_PAY_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ELW_LSTTRD_DD, "yyyyMMdd");
    $c.date.compareFromToDate(edt_EXER_STRT_DD, edt_EXER_END_DD, ["행사시작일", "행사종료일"]);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목 찾기(돋보기) 버튼 클릭 — 종목을 고르면 바로 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.btn_Update_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectIsu
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장원부 상세 조회 → dma_detail. 기관·주간사 콤보에 현재 값을 넣는다. (원본 fn_read_sync 1번째 dts_Isu readIssueBook — §5.1)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectIsu = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/listed-register/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    // TODO: 원본이 URL 에 붙이던 SECUGRP_ID(EW)·SCREN_ID·SCREN_PROCES_TP_CD(01) 는 명세에 없어 보내지 않는다 (§10 #6)
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;

    scwin.applyInstItems();
    return true;
};

/**
 * @method
 * @name scwin.selectLp
 * @author Inswave
 * @date 2026. 10. 28
 * @description 유동성공급자(LP) 목록 조회 → dlt_lp. (원본 fn_read_sync 2번째 dts_LP readLpMbrNoIssueBook — §5.2)
 * @param {String} isuCd 종목코드
 * @returns
 * @hidden N
 */
scwin.selectLp = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectLp",
        method : "get",
        action : "/api/listing/lstproc/elw/listed-register/select-list-lp",
        target : "dlt_lp=body",
        gridview : "grd_LP_MBR_NO",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
};

/**
 * @method
 * @name scwin.selectUly
 * @author Inswave
 * @date 2026. 10. 28
 * @description 기초자산 목록 조회 → dlt_uly. (원본 fn_read_sync 3번째 dts_UlyIsu readUlyIssueBook — §5.3)
 * @param {String} isuCd 종목코드
 * @returns
 * @hidden N
 */
scwin.selectUly = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectUly",
        method : "get",
        action : "/api/listing/lstproc/elw/listed-register/select-list-uly",
        target : "dlt_uly=body",
        gridview : "grd_ULY_ISU_CD",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장원부 수정. dma_detail 의 명세 키를 dma_save 에 옮기고 업무처리번호·발행기관코드를 채워 ref 로 보낸다.
 * 응답(dma_saveResult)의 completeYn 이 실패가 아니면 MSG-A001 안내 후 다시 조회, 실패면 resultMessage(없으면 MSG-A002). (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.4)
 * @param {String} bzProcsNo 새로 받은 업무처리번호
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (bzProcsNo) {
    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : "/api/listing/lstproc/elw/listed-register/modify",
        ref : "dma_save",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 전문 준비 — setJSON 은 dma_save 에 정의된 명세 키만 남긴다(조회 전용 키는 보내지 않음).
    // TODO: 원본 trs Parameters 의 TRS_IDX(2)·SECUGRP_ID(EW)·LIST_BZ_TP_CD(309)·SCREN_ID·세션은 명세에 없어 보내지 않는다 (§10 #6)
    // TODO: 화면에서 고칠 수 있는 청약일·납입일·전환비율(subsDd·payDd·elwConvRto)이 명세 요청에 없다 (§10 #2)
    dma_save.setEmptyValue();
    dma_save.setJSON(dma_detail.getJSON());
    dma_save.set("bzProcsNo", bzProcsNo);
    dma_save.set("isurCd", dma_search.get("isurCd"));
    dma_saveResult.setEmptyValue();

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    // TODO: completeYn 은 명세상 text 라 값 형식(Y/N·true/false)이 정해지지 않았다 — 실패 표기("N"·"false")만 실패로 본다 (§10 #7)
    const completeYn = String(dma_saveResult.get("completeYn") ?? "");
    if (!result.responseJSON?.success || completeYn === "N" || completeYn === "false") {
        const resultMessage = dma_saveResult.get("resultMessage");
        await $c.win.alert($c.util.isEmpty(resultMessage) ? $c.stf.getMessageParam("MSG-A002", "수정") : resultMessage);
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    await scwin.searchAll();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장종목찾기(ULDSTF92017) — 고른 종목을 조회 조건에 넣고 바로 조회한다.
 * (원본 fn_GetPar/fn_SetPar 바꿔 끼우기 + fn_PopFindIsu + fn_SetParIsuCd — §6.1)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // 원본 fn_GetParIsuCd: arrPar[2] = 증권그룹ID(EW). arrPar[1](현재 종목명)은 92017 이 받지 않는다 (§10 #4)
    const result = await $c.lc.popFindIsu($c.lc.glb.SECUGRP_ID_EW);

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정한다(원본 DBCLICKYN "Y" 일 때만 반영).
    if ($c.util.isEmpty(result?.isuCd)) return;

    // 원본 fn_SetParIsuCd — 종목코드·명, 발행기관코드(vIsurCd)
    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuKorNm", result.isuKorNm ?? "");
    dma_search.set("isurCd", result.isurCd ?? "");

    await scwin.searchAll();
};

/**
 * @method
 * @name scwin.searchAll
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장원부 전체 조회 — 상세 → 유동성공급자 → 기초자산 순서(원본 동기 조회 3회와 같은 순서).
 * 이전 종목의 값이 남아 다른 종목으로 수정되지 않게 먼저 비운다. (원본 fn_read_sync — §1.4 업무 2)
 * @returns
 * @hidden N
 */
scwin.searchAll = async function () {
    const isuCd = dma_search.get("isuCd");

    dma_detail.setEmptyValue();
    dlt_lp.removeAll();
    dlt_uly.removeAll();

    if (!await scwin.selectIsu(isuCd)) return;
    await scwin.selectLp(isuCd);
    await scwin.selectUly(isuCd);
};

/**
 * @method
 * @name scwin.applyInstItems
 * @author Inswave
 * @date 2026. 10. 28
 * @description 기관·주간사 콤보에 조회한 현재 값(코드·명)을 목록 항목으로 넣고 다시 선택한다 — 목록 API 가 없어 값이 빈 칸으로 보이지 않게. (§6.4)
 * @returns
 * @hidden N
 */
scwin.applyInstItems = function () {
    // TODO: 기관·주간사 목록 API 가 정해지면 init 에서 목록을 채우고 이 보강은 지운다 (§10 #3)
    scwin.INST_COMBOS.forEach(item => {
        const code = dma_detail.get(item.codeKey);
        if ($c.util.isEmpty(code)) return;

        const list = $p.getComponentById(item.list);
        if (list.getMatchedIndex(item.codeCol, code, true).length < 1) {
            const row = list.insertRow();
            list.setCellData(row, item.codeCol, code);
            list.setCellData(row, item.nameCol, dma_detail.get(item.nameKey) || code);
        }
        $p.getComponentById(item.comp).setValue(code);
    });
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 전 검증 — 종목을 조회했는지만 본다. (원본 fn_CheckForm — §6.2)
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.validate = async function () {
    if ($c.util.isEmpty(dma_detail.get("isuCd"))) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내 문자열로 만든다. (§5.5)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 명세 dma_save.bzProcsNo 주석의 채번 경로(/api/listing/common/bzprocsno/create)와 pcc 의 채번 경로가 다르다 (§10 #5)
    const res = await $c.stf.getNewBzProcNo();
    const body = (res !== null && typeof res === "object") ? res.body : res;
    const no = (body !== null && typeof body === "object") ? body.bzProcsNo : body;
    return String(no ?? "");
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 확인 → 채번(14자리 아니면 MSG-0010) → 수정 순서. 채번이 확인보다 뒤라 취소한 건에는 번호가 소비되지 않는다. (원본 fn_update — §6.3, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== scwin.BZ_PROCS_NO_LEN) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    await scwin.saveTrs(bzProcsNo);
};
